#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/moduleparam.h>

static int count = 1;
static char *who = "world";

/* 0444 exposes the parameter read-only under /sys/module/<name>/parameters/ */
module_param(count, int, 0444);
MODULE_PARM_DESC(count, "number of greetings");
module_param(who, charp, 0444);
MODULE_PARM_DESC(who, "who to greet");

static int __init params_init(void)
{
    int i;
    for (i = 0; i < count; i++)
        pr_info("params: hello %s (%d/%d)\n", who, i + 1, count);
    return 0;
}

static void __exit params_exit(void)
{
    pr_info("params: goodbye %s\n", who);
}

module_init(params_init);
module_exit(params_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("Demonstrates module parameters");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/fs.h>
#include <linux/uaccess.h>

#define DEVICE_NAME "vqchar"
static int major;
static const char message[] = "Hello from the kernel char device\n";

static ssize_t dev_read(struct file *f, char __user *ubuf, size_t len, loff_t *off)
{
    /* simple_read_from_buffer handles *off and returns 0 at EOF, so cat stops */
    return simple_read_from_buffer(ubuf, len, off, message, sizeof(message) - 1);
}

static const struct file_operations fops = {
    .owner = THIS_MODULE,
    .read = dev_read,
};

static int __init chardev_init(void)
{
    major = register_chrdev(0, DEVICE_NAME, &fops);   /* 0 = pick a free major */
    if (major < 0) {
        pr_err("vqchar: register_chrdev failed: %d\n", major);
        return major;
    }
    pr_info("vqchar: major %d; create node: sudo mknod /dev/%s c %d 0\n",
            major, DEVICE_NAME, major);
    return 0;
}

static void __exit chardev_exit(void)
{
    unregister_chrdev(major, DEVICE_NAME);
    pr_info("vqchar: unregistered\n");
}

module_init(chardev_init);
module_exit(chardev_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("A read-only character device using simple_read_from_buffer");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/slab.h>

#define N 64
static int *buf;

static int __init kmem_init(void)
{
    long sum = 0;
    int i;

    buf = kmalloc_array(N, sizeof(int), GFP_KERNEL);   /* may sleep; not in atomic ctx */
    if (!buf)
        return -ENOMEM;                                /* always check allocations */
    for (i = 0; i < N; i++)
        buf[i] = i;
    for (i = 0; i < N; i++)
        sum += buf[i];
    pr_info("kmem: sum of 0..%d = %ld\n", N - 1, sum);  /* 2016 */
    return 0;
}

static void __exit kmem_exit(void)
{
    kfree(buf);                                        /* free exactly what you kmalloc'd */
    pr_info("kmem: freed\n");
}

module_init(kmem_init);
module_exit(kmem_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("Kernel memory allocation with kmalloc_array/kfree");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/mutex.h>
#include <linux/atomic.h>

static DEFINE_MUTEX(lock);                 /* mutex: may sleep; for process context */
static int shared;                         /* protected by lock */
static atomic_t hits = ATOMIC_INIT(0);     /* lock-free counter */

static void bump(void)
{
    mutex_lock(&lock);
    shared++;                              /* critical section */
    mutex_unlock(&lock);
    atomic_inc(&hits);                     /* no lock needed for a simple counter */
}

static int __init sync_init(void)
{
    int i;
    for (i = 0; i < 100; i++)
        bump();
    pr_info("sync: mutex-guarded=%d atomic=%d\n", shared, atomic_read(&hits));
    return 0;
}

static void __exit sync_exit(void)
{
    pr_info("sync: final=%d\n", shared);
}

module_init(sync_init);
module_exit(sync_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("Mutex and atomic counters");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/workqueue.h>

static struct work_struct deferred;

/* A workqueue handler runs later in PROCESS context, so it may sleep. */
static void work_handler(struct work_struct *w)
{
    pr_info("work: deferred handler ran in process context\n");
}

static int __init work_init(void)
{
    INIT_WORK(&deferred, work_handler);
    schedule_work(&deferred);          /* queue the bottom half */
    pr_info("work: scheduled deferred work\n");
    return 0;
}

static void __exit work_exit(void)
{
    cancel_work_sync(&deferred);       /* wait for the handler before unloading */
    pr_info("work: flushed and exiting\n");
}

module_init(work_init);
module_exit(work_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("Deferred work with a workqueue (bottom half)");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/proc_fs.h>
#include <linux/uaccess.h>

#define PROC_NAME "vqinfo"
static struct proc_dir_entry *entry;

static ssize_t info_read(struct file *f, char __user *ubuf, size_t len, loff_t *off)
{
    static const char text[] = "VoltQuest kernel info: hello from /proc\n";
    return simple_read_from_buffer(ubuf, len, off, text, sizeof(text) - 1);
}

/* Since Linux 5.6, /proc entries use proc_ops, not file_operations. */
static const struct proc_ops pops = {
    .proc_read = info_read,
};

static int __init procfs_init(void)
{
    entry = proc_create(PROC_NAME, 0444, NULL, &pops);
    if (!entry)
        return -ENOMEM;
    pr_info("vqinfo: created /proc/%s\n", PROC_NAME);
    return 0;
}

static void __exit procfs_exit(void)
{
    proc_remove(entry);
    pr_info("vqinfo: removed /proc/%s\n", PROC_NAME);
}

module_init(procfs_init);
module_exit(procfs_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("A /proc entry using proc_ops (Linux 5.6+)");

#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/fs.h>
#include <linux/mutex.h>
#include <linux/uaccess.h>

#define DEVICE_NAME "charbuf"
#define BUF_SIZE 1024

static int major;
static char buffer[BUF_SIZE];
static size_t data_len;
static DEFINE_MUTEX(buf_lock);     /* mutex: the copy_*_user calls below can sleep */

static ssize_t cb_read(struct file *f, char __user *ubuf, size_t len, loff_t *off)
{
    ssize_t ret;
    mutex_lock(&buf_lock);
    ret = simple_read_from_buffer(ubuf, len, off, buffer, data_len);
    mutex_unlock(&buf_lock);
    return ret;
}

static ssize_t cb_write(struct file *f, const char __user *ubuf, size_t len, loff_t *off)
{
    ssize_t ret;
    if (*off >= BUF_SIZE)
        return -ENOSPC;           /* buffer full: fail, don't return 0 (that loops write()) */
    mutex_lock(&buf_lock);
    ret = simple_write_to_buffer(buffer, BUF_SIZE, off, ubuf, len);
    if (ret >= 0)
        data_len = *off;          /* remember how much valid data we hold */
    mutex_unlock(&buf_lock);
    return ret;
}

static const struct file_operations fops = {
    .owner = THIS_MODULE,
    .read = cb_read,
    .write = cb_write,
};

static int __init charbuf_init(void)
{
    major = register_chrdev(0, DEVICE_NAME, &fops);
    if (major < 0)
        return major;
    pr_info("charbuf: major %d; sudo mknod /dev/%s c %d 0\n", major, DEVICE_NAME, major);
    return 0;
}

static void __exit charbuf_exit(void)
{
    unregister_chrdev(major, DEVICE_NAME);   /* reverse of init */
    pr_info("charbuf: unloaded\n");
}

module_init(charbuf_init);
module_exit(charbuf_exit);

MODULE_LICENSE("GPL");
MODULE_AUTHOR("VoltQuest");
MODULE_DESCRIPTION("A mutex-protected in-kernel buffer character device");
